import{_ as n,l as s,o as e,c as o,v as t,p as l,x as r,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"恰好一次","description":"","frontmatter":{"title":"恰好一次","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/exactly-once.md","filePath":"cs/exactly-once.md","lastUpdated":1789023840000}'),h={name:"cs/exactly-once.md"};function _(k,a,m,f,u,E){const i=s("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="恰好一次" tabindex="-1">恰好一次 <a class="header-anchor" href="#恰好一次" aria-label="Permalink to &quot;恰好一次&quot;">​</a></h1><div class="epigraph"><p>端到端恰好一次不是「消息只投一次」，而是效果幂等：重复投递不改变状态。检查点、事务 sink 与去重键一起才够。</p><footer>—— 据流系统 exactly-once 实践（Kafka transactions、Flink 检查点）；网络课重试幂等对照</footer></div><p><a href="/cs/watermark-late-events">上一课</a>让窗口能关。缺口是故障：算子重跑会把同一窗口结果写两遍。本课钉恰好一次；TPC 下一课换成基准，不在这里写协议细节到可利用的程度。与 <a href="/cs/retry-idempotency">重试幂等</a> 对照：那是 RPC，这是流状态。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>至少一次：简单，重复。至多一次：丢。恰好一次：需要 (1) 输入可重放；(2) 算子状态与输入偏移一起检查点；(3) sink 事务或幂等键。缺口是<strong>效果</strong>，不是网卡只发一帧。外部副作用（发邮件）没有事务就只能幂等。</p><p><span class="marginnote">「Kafka exactly-once」指事务生产者与读已提交；跨多个异构 sink 仍要自己的幂等设计。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>检查点：对齐或非对齐 barrier，状态后端快照。sink：两阶段提交或按主键 upsert。去重：事件 ID 在窗口内。失败：从检查点重放，sink 回滚或覆盖。与湖仓：表快照提交是事务 sink。</p>',8)),(e(),l(p,null,{default:r(()=>[d(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%8F%AF%E9%87%8D%E6%94%BE%E8%BE%93%E5%85%A5%22%5D%20--%3E%20CKPT%5B%22%E7%8A%B6%E6%80%81%20%2B%20%E5%81%8F%E7%A7%BB%22%5D%0A%20%20CKPT%20--%3E%20SINK%5B%22%E4%BA%8B%E5%8A%A1%20%2F%20%E5%B9%82%E7%AD%89%E5%86%99%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>确定性重算 + 原子提交使第二次效果等于第一次。非确定性（随机、系统时间当事件时间）会打破。barrier 对齐等待最慢分区，与 watermark 的 min 同类。检查点间隔即 RPO：未检查点的丢失像异步提交。事务 sink 把偏移与写出同一提交；否则至少一次加下游幂等键（窗口+键+版本）。</p><p>CDC 槽推进类似偏移提交。杀工人重放是测试手段，不是协议漏洞利用。端到端三处对齐：源、状态、sink 缺一则重复或丢。外部副作用（邮件）没有事务就只能幂等。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不提供绕过幂等去刷写外部系统的办法。下一课基准测吞吐，不测你是否真 exactly-once。Jepsen 再后课测隔离声明。跨多个异构 sink 仍要各自的幂等设计，单靠 Kafka 事务不够。</p><p>后课默认：跨系统用幂等或事务对齐偏移。没有幂等键的「事务 sink」在非事务下游上仍会重复。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>恰好一次是状态效果幂等，不是物理只投一次。</li><li>检查点必须绑输入偏移；sink 要事务或幂等键。</li><li>TPC-C / TPC-H 下一课。</li><li>出处：流引擎检查点与 Kafka 事务公开设计；对照网络幂等课。</li></ul>',8))])}const P=n(h,[["render",_]]);export{x as __pageData,P as default};
